$allKeys = [];
$controller = file_get_contents($root . '/app/Http/Controllers/SolutionController.php');
preg_match_all("/=>\s*'((?:\\\\'|[^'])*)'/", $controller, $values);
foreach ($values[1] as $value) {
    $value = stripcslashes($value);
    if ($value === '' || str_contains($value, '#') || str_contains($value, 'rgba(') || str_starts_with($value, 'ti-') || preg_match('/^[a-z0-9-]+$/', $value)) {
        continue;
    }
    $allKeys[$value] = true;
}

$blade = file_get_contents($root . '/resources/views/pages/solution-detail.blade.php');
preg_match_all("/__\(\s*'((?:\\\\'|[^'])*)'\s*\)/", $blade, $single);
preg_match_all('/__\(\s*"((?:\\\\"|[^"])*)"\s*\)/', $blade, $double);
foreach (array_merge($single[1], $double[1]) as $value) {
    $value = stripcslashes($value);
    if ($value !== '') {
        $allKeys[$value] = true;
    }
}

foreach (array_keys($allKeys) as $key) {
    $maps['en'][$key] ??= $key;
}

foreach (['fr', 'es', 'it', 'zh'] as $locale) {
    foreach (array_keys($allKeys) as $key) {
        if (!isset($maps[$locale][$key])) {
            $maps[$locale][$key] = $maps['fr'][$key] ?? $key;
        }
    }
}

foreach ($maps as $locale => $entries) {
    $path = $root . "/resources/lang/{$locale}.json";
    $json = json_decode(file_get_contents($path), true) ?: [];
    foreach ($entries as $key => $value) {
        $json[$key] = $value;
    }
    ksort($json, SORT_NATURAL | SORT_FLAG_CASE);
    file_put_contents($path, json_encode($json, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) . PHP_EOL);
}

echo "solution detail translations completed for " . count($allKeys) . " keys\n";
